WITH unpacked AS (SELECT id, service, level, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, SHIFTRIGHT(status_code, 2) AS status_code_high FROM app_logs) SELECT *, NTILE(10) OVER (PARTITION BY service, tier ORDER BY status_code_high DESC, id) AS status_code_high_bucket, MIN(status_code_high) OVER w_grp AS tier_min_status_code_high, SUM(status_code_high) OVER w_grp AS tier_sum_status_code_high, FIRST_VALUE(status_code_high, TRUE) OVER (PARTITION BY level, tier ORDER BY status_code_high, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_status_code_high FROM unpacked WINDOW w_grp AS (PARTITION BY tier)
